sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        //hiding reset Amend fields if outcome is not selected or onLoad
        //g_form.setDisplay('reset_amend_field', false);

        /*Artifacts Included

		1) Field : reset_amend_field - On MSS Custody Task
		2 )Client Script - OnLoad - to populate options - Populate Reset Amend Field OnLoad - Task
		3) Client Script - MSS Trade Amend Reset OnChange - Task
		4) Script Include - MSSCustodyAmendUtils


		System Property : x_hsb11_mss_c_proc.getfieldlabelsamend.outcomes // add the new field options in property 
		Thsi will Impact Client Script: Populate Reset Amend Field OnLoad - Task
		TradesArray Also has to be added with relevant trade

		Working Logic : 1) Sytem Property x_hsb11_mss_c_proc.getfieldlabelsamend.outcomes - holds the backend values of the bulk table which is utilised
		as extended fields on task
		2) From the trade all the listed amend fields are retrieved and stored in TradesArray
		3) The Backend values of the field are retrived from system property and concatenated with bulk_id and stored in values array
		4) When user selects a field relevant field is reverted back using common compariosn between the bulk_id + newValue and the concatenated backend value from the system property

		Artifacts Included
		*/
        return;
    }


    //Configuration Check
    var eligbleCheck = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
    eligbleCheck.addParam('sysparm_name', 'evalAmendEligibility');
    eligbleCheck.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
    eligbleCheck.addParam('sysparm_recSysID', g_form.getUniqueValue());
    eligbleCheck.addParam('sysparm_tableName', 'x_hsb11_mss_c_proc_mss_custody_task');
    eligbleCheck.getXMLAnswer(handleEligiblity);

    function handleEligiblity(check) {
        if (check.toString() == 'true') {
            var tradeData = g_form.getReference('trade_id', getTradeData);
        } else {
            return;
        }
    }  
	//Configuration Check




    function getTradeData(tradeData) {

        var tradeDataArray = []; //Values from the trade

        var securityID = tradeData.security_id;
        var tradeDate = tradeData.trade_date;
        var settlementDate = tradeData.settlement_date;
        var dealPrice = tradeData.deal_price;
        var dealCurrency = tradeData.deal_price_currency;
        var settlementCurrency = tradeData.settlement_amount_currency;
        var settlementAmount = tradeData.settlement_amount;
        var counterPartyRef = tradeData.counterparty_reference;
        var cusRef = tradeData.customer_reference;
        var locCode = tradeData.location_code;
        var hmiIndicator = tradeData.hold_matched_si_indicator;
        var scripholIndicator = tradeData.script_hold_indicator;
        var cashHoldIndicator = tradeData.cash_hold_indicator;
        var gdiIncidcator = tradeData.gdi_indicator;
        var payMethod = tradeData.cash_payment_method;
        var switchIndicator = tradeData.switch_indicator;
        var switchAcc = tradeData.switch_account;
        var counterParCode = tradeData.counterparty_code;
        var delivererCusBic = tradeData.receiver_deliverer_custodian_bic;
        var sellBuyBic = tradeData.buyer_seller_bic;
        var placeofSett = tradeData.place_of_settlement_95a_qualifier_pset;
        var susAccNum = tradeData.suspense_account_number;
        var counterSettAccNum = tradeData.counterparty_settlement_account_number;
        var converAccSwitch = tradeData.convert_to_account_switching;
        var accOfClient = tradeData.a_c_of_client;

        tradeDataArray.push(securityID, tradeDate, settlementDate, dealPrice, dealCurrency, settlementCurrency, settlementAmount, counterPartyRef, cusRef, locCode, hmiIndicator, scripholIndicator, cashHoldIndicator, gdiIncidcator, payMethod, switchIndicator, switchAcc, counterParCode, delivererCusBic, sellBuyBic, placeofSett, susAccNum, counterSettAccNum, converAccSwitch, accOfClient);


        //fetch Valuesfrom system property to populate the field
        var getReverFieldlabels = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
        getReverFieldlabels.addParam('sysparm_name', 'getAmendBulkFieldLabels');
        getReverFieldlabels.addParam('sysparm_bulkValue', 'false');
        getReverFieldlabels.addParam('sysparm_taskMode', 'automatedTask');
        getReverFieldlabels.getXMLAnswer(handleResponse);

        function handleResponse(response) {
            var values = [];
            var countofAmendFields = response.split(",").length; //from property

            //appending all the backend name of the bulk fields from the property along with bulk_id
            for (var i = 0; i < countofAmendFields; i++) {
                var getFieldBackend = response.split(",")[i];
                getFieldBackend = getFieldBackend.split(":")[0];
                values.push("bulk_id." + getFieldBackend);
            }
            //appending all the backend name of the bulk fields from the property along with bulk_id


            //backend value of choice(on property) and backend value of the field(on Bulk) should be same

            for (var j = 0; j < values.length; j++) {
                var fieldToRevert = "bulk_id." + newValue; //concatinating field new Value to bulk_id field since extended from bulk
                if (fieldToRevert == values[j]) {
                    g_form.setValue(fieldToRevert, tradeDataArray[j]);
                    g_form.clearValue('reset_amend_field');
                    break;
                }
            }

        }
    }


}
